window.TICKER_CARDS = [{"id":"japan-vocab-01-01","deck":"fareast","topic":"Greetings","q":"How do you say 'hello' (daytime greeting) in Japanese?","a":"konnichiwa","accept":["konnichi wa","konnichiha"],"wrong":["sayōnara","kombanwa","oyasuminasai"],"explain":"Konnichiwa (こんにちは) is the everyday greeting; the Wikivoyage phrasebook glosses it as 'Good afternoon.'","hook":"Sounds like 'cone-knee-chee-wah'.","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Good afternoon. こんにちは。 Konnichiwa. (kon-nee-chee-wah)"}],"say":"kon-nee-chee-wah","kana":"こんにちは","romaji":"konnichiwa","score":97},{"id":"japan-vocab-01-02","deck":"fareast","topic":"Greetings","q":"How do you say 'good morning' (polite) in Japanese?","a":"ohayō gozaimasu","accept":["ohayo gozaimasu","ohayou gozaimasu"],"wrong":["oyasuminasai","kombanwa","arigatō gozaimasu"],"explain":"Ohayō gozaimasu is the polite form; plain ohayō is the informal version.","hook":"'Ohio' + 'go-zai-mahs'.","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Good morning. お早うございます。 Ohayō gozaimasu. (oh-hah-YOH go-zah-ee-mahs)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Good morning. (informal) おはよう。 Ohayō."}],"say":"oh-hah-yoh go-zah-ee-mahs","kana":"おはようございます","romaji":"ohayō gozaimasu","score":98},{"id":"japan-vocab-01-03","deck":"fareast","topic":"Courtesy","q":"How do you say 'thank you' in Japanese?","a":"arigatō","accept":["arigato","arigatou"],"wrong":["konnichiwa","dōzo","sayōnara"],"explain":"Arigatō is the normal 'thank you'; adding gozaimasu (arigatō gozaimasu) makes it more polite.","hook":"'Alligator' said quickly: ah-ree-gah-toh.","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Thank you. (normal) ありがとう。 Arigatō. (ah-ree-GAH-toh)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Thank you. (less formal) ありがとうございます。 Arigatō gozaimasu."}],"say":"ah-ree-gah-toh","kana":"ありがとう","romaji":"arigatō","score":97},{"id":"japan-vocab-01-04","deck":"fareast","topic":"Courtesy","q":"How do you say 'excuse me' in Japanese?","a":"sumimasen","accept":["suimasen"],"wrong":["arigatō","onegaishimasu","wakarimasen"],"explain":"Sumimasen means 'excuse me' and is also what you say to get a waiter's attention.","hook":"'Sue-me-mah-sen'.","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Excuse me. すみません。 Sumimasen. (soo-mee-mah-sen)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Excuse me, waiter? ( getting attention of server ) すみません。 ( sumimasen )"}],"say":"soo-mee-mah-sen","kana":"すみません","romaji":"sumimasen","score":97},{"id":"japan-vocab-01-05","deck":"fareast","topic":"Courtesy","q":"How do you say 'I'm sorry' in Japanese?","a":"gomen nasai","accept":["gomennasai","gomen"],"wrong":["hai","dōzo","arigatō"],"explain":"Gomen nasai means 'I'm sorry'; the shorter gomen is the informal version.","hook":"'Go-men, nah-sigh'.","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"I'm sorry. ごめんなさい。 Gomen nasai. (goh-men-nah-sah-ee)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"I'm sorry. (informal) ごめん Gomen. (goh-men)"}],"say":"goh-men-nah-sah-ee","kana":"ごめんなさい","romaji":"gomen nasai","score":97},{"id":"japan-vocab-01-06","deck":"fareast","topic":"Courtesy","q":"How do you say 'please' when making a request in Japanese?","a":"onegaishimasu","accept":["onegai shimasu"],"wrong":["arigatō","itadakimasu","oyasuminasai"],"explain":"Onegai shimasu is 'please' for a request; for offering something, Japanese uses dōzo instead.","hook":"'Oh-neh-guy she-mahs'.","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Please. (request) お願いします。 Onegai shimasu. (oh-neh-gah-ee shee-mahs)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Please. (offer) どうぞ。 Dōzo. (Dohh-zoh)"}],"say":"oh-neh-gah-ee-shee-mahs","kana":"おねがいします","romaji":"onegaishimasu","kanji":"お願いします","score":95},{"id":"japan-vocab-01-07","deck":"fareast","topic":"Courtesy","q":"How do you say 'please' when offering something (as in 'go ahead') in Japanese?","a":"dōzo","accept":["dozo","douzo"],"wrong":["onegaishimasu","dōmo","hai"],"explain":"Dōzo is 'please' when offering; onegai shimasu is 'please' when requesting.","hook":"Offering? 'Doh-zoh' - 'do, go ahead'.","difficulty":3,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Please. (offer) どうぞ。 Dōzo. (Dohh-zoh)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Please. (request) お願いします。 Onegai shimasu."}],"say":"doh-zoh","kana":"どうぞ","romaji":"dōzo","score":97},{"id":"japan-vocab-01-08","deck":"fareast","topic":"Courtesy","q":"How do you say 'yes' in Japanese?","a":"hai","accept":[],"wrong":["iie","dare","nani"],"explain":"Hai means 'yes' and is pronounced like the English word 'high'.","hook":"Yes = 'high' five.","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"yes はい。 hai (High)"}],"say":"high","kana":"はい","romaji":"hai","score":98},{"id":"japan-vocab-01-09","deck":"fareast","topic":"Courtesy","q":"How do you say 'no' in Japanese?","a":"iie","accept":["iye"],"wrong":["hai","ikura","itsu"],"explain":"Iie means 'no' and is pronounced roughly 'EE-eh'.","hook":"'Ee-eh?' - no way.","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"no いいえ。 iie (EE-eh)"}],"say":"ee-eh","kana":"いいえ","romaji":"iie","score":96},{"id":"japan-vocab-01-10","deck":"fareast","topic":"Numbers","q":"How do you say the number 1 in Japanese?","a":"ichi","accept":[],"wrong":["ni","san","hachi"],"explain":"Ichi (一) is the standard reading of 1; the native counting form is hitotsu.","hook":"'Itchy' - number one.","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"1 一 / 壱 ( ichi )"},{"url":"https://en.wikipedia.org/wiki/Japanese_numerals","title":"Japanese numerals - Wikipedia","quote":"| 1 | 一 | ichi ( いち ) | hito(tsu) ( ひと・つ ) | ichi ( いち ) |"}],"say":"ee-chee","kana":"いち","romaji":"ichi","kanji":"一","score":99},{"id":"japan-vocab-01-11","deck":"fareast","topic":"Numbers","q":"How do you say the number 3 in Japanese?","a":"san","accept":[],"wrong":["ni","go","roku"],"explain":"San (三) is the standard reading of 3; the native counting form is mittsu.","hook":"Three = 'sahn'.","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"3 三 / 参 ( san )"},{"url":"https://en.wikipedia.org/wiki/Japanese_numerals","title":"Japanese numerals - Wikipedia","quote":"| 3 | 三 | san ( さん ) | mit(tsu) ( みっ・つ ) | san ( さん ) |"}],"say":"sahn","kana":"さん","romaji":"san","kanji":"三","score":99},{"id":"japan-vocab-01-12","deck":"fareast","topic":"Numbers","q":"What is the usual way to say the number 4 in Japanese?","a":"yon","accept":[],"wrong":["go","roku","hachi"],"explain":"4 can be read yon or shi; yon is used in most situations, reportedly due to superstition because shi also means 'death'.","hook":"4 = 'yawn'.","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"4 四 ( yon or shi )"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Note that, due to superstition ( shi also means \"death\"), the native Japanese readings yon and nana or 4 and 7 are used instead in most situations, though the Sino-Japanese readings shi and shichi respectively are more commonly used when counting."},{"url":"https://en.wikipedia.org/wiki/Japanese_numerals","title":"Japanese numerals - Wikipedia","quote":"As noted above, yon (4) and nana (7) are preferred to shi and shichi."}],"say":"yohn","kana":"よん","romaji":"yon","kanji":"四","score":97},{"id":"japan-vocab-01-13","deck":"fareast","topic":"Numbers","q":"What is the usual way to say the number 7 in Japanese?","a":"nana","accept":[],"wrong":["hachi","kyū","roku"],"explain":"7 is read nana or shichi; nana is preferred in most situations, while shichi is common when counting.","hook":"7 = 'nah-nah' (like 'nana').","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"7 七 ( nana or shichi )"},{"url":"https://en.wikipedia.org/wiki/Japanese_numerals","title":"Japanese numerals - Wikipedia","quote":"| 7 | 七 | shichi ( しち ) | nana(tsu) ( なな・つ ) | nana ( なな ) |"},{"url":"https://en.wikipedia.org/wiki/Japanese_numerals","title":"Japanese numerals - Wikipedia","quote":"As noted above, yon (4) and nana (7) are preferred to shi and shichi."}],"say":"nah-nah","kana":"なな","romaji":"nana","kanji":"七","score":97},{"id":"japan-vocab-01-14","deck":"fareast","topic":"Numbers","q":"How do you say the number 9 in Japanese?","a":"kyū","accept":["kyu","kyuu","ku"],"wrong":["jū","hachi","roku"],"explain":"Kyū (九) is the preferred reading of 9; ku is an alternative reading.","hook":"Nine = 'cue'.","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"9 九 ( kyū )"},{"url":"https://en.wikipedia.org/wiki/Japanese_numerals","title":"Japanese numerals - Wikipedia","quote":"| 9 | 九 | ku , kyū ( く, きゅう ) | kokono(tsu) ( ここの・つ ) | kyū ( きゅう ) |"}],"say":"kyoo","kana":"きゅう","romaji":"kyū","kanji":"九","score":98},{"id":"japan-vocab-01-15","deck":"fareast","topic":"Numbers","q":"How do you say the number 10 in Japanese?","a":"jū","accept":["ju","juu","jyuu"],"wrong":["kyū","hyaku","sen"],"explain":"Jū (十) is the standard reading of 10; tens are built from it, e.g. ni-jū for 20.","hook":"Ten = 'joo'.","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"10 十 / 拾 ( jū )"},{"url":"https://en.wikipedia.org/wiki/Japanese_numerals","title":"Japanese numerals - Wikipedia","quote":"| 10 | 十 | jū ( じゅう ) | tō ( とお ) | jū ( じゅう ) |"},{"url":"https://en.wikipedia.org/wiki/Japanese_numerals","title":"Japanese numerals - Wikipedia","quote":"Tens from 20 to 90 are \"(digit) -jū \" as in 二十 ( ni-jū ) to 九十 ( kyū-jū ) ."}],"say":"joo","kana":"じゅう","romaji":"jū","kanji":"十","score":99},{"id":"japan-vocab-01-16","deck":"fareast","topic":"Question words","q":"How do you say 'what?' in Japanese?","a":"nani","accept":["nan"],"wrong":["doko","dare","itsu"],"explain":"Nani means 'what?'; it often becomes nan before desu, as in kore wa nan desu ka ('what is this?').","hook":"'Nah-nee?' - what?","difficulty":1,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"What? 何？ Nani? (nah-nee)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"これは何ですか？ Kore wa nan desu ka? (\"What [is] this?\")"}],"say":"nah-nee","kana":"なに","romaji":"nani","kanji":"何","score":95},{"id":"japan-vocab-01-17","deck":"fareast","topic":"Question words","q":"How do you say 'where?' in Japanese?","a":"doko","accept":[],"wrong":["dore","itsu","nani"],"explain":"Doko means 'where?', as in toire wa doko desu ka ('where is the toilet?').","hook":"'Dough-co' - where's the dough?","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Where? どこ？ Doko? (doh-koh)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Where is the toilet? お手洗い・トイレはどこですか？ Otearai/toire wa doko desu ka?"}],"say":"doh-koh","kana":"どこ","romaji":"doko","score":98},{"id":"japan-vocab-01-18","deck":"fareast","topic":"Question words","q":"How do you say 'when?' in Japanese?","a":"itsu","accept":[],"wrong":["doko","dare","ikura"],"explain":"Itsu means 'when?'.","hook":"'It-soo' - when is it, Sue?","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"When? いつ？ Itsu? (it-soo)"}],"say":"ee-tsoo","kana":"いつ","romaji":"itsu","score":98},{"id":"japan-vocab-01-19","deck":"fareast","topic":"Question words","q":"How do you say 'who?' in Japanese?","a":"dare","accept":["dare?"],"wrong":["dore","doko","nani"],"explain":"Dare means 'who?', as in anata wa dare desu ka ('who are you?'). Do not confuse it with dore ('which?').","hook":"'Dah-reh' - who dares?","difficulty":3,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Who? 誰？ Dare? (dah-reh)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"あなたはだれですか？ Anata wa dare desu ka? (\"Who [are] you?\")"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"Which? どれ？ Dore? (doh-reh)"}],"say":"dah-reh","kana":"だれ","romaji":"dare","kanji":"誰","score":98},{"id":"japan-vocab-01-20","deck":"fareast","topic":"Question words","q":"How do you say 'how much?' (price) in Japanese?","a":"ikura","accept":[],"wrong":["itsu","doko","dore"],"explain":"Ikura means 'how much?'; ikura desu ka is 'how much is this?' when shopping.","hook":"'Ee-koo-rah?' - how much?","difficulty":2,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"How much? いくら？ Ikura? (ee-koo-rah)"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"How much is this? いくらですか？ ( Ikura desu ka? )"}],"say":"ee-koo-rah","kana":"いくら","romaji":"ikura","score":98},{"id":"japan-vocab-01-21","deck":"fareast","topic":"Polite phrases","q":"How do you say 'you're welcome' in Japanese?","a":"dō itashimashite","accept":["do itashimashite","dou itashimashite","doitashimashite"],"wrong":["arigatō gozaimasu","gochisōsama deshita","sumimasen"],"explain":"Dō itashimashite is the reply to a thank-you, meaning 'you're welcome'.","hook":"'Don't touch my mustache' - doh-ee-tah-shee-mah-shteh.","difficulty":3,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"You're welcome. どういたしまして。 Dō itashimashite. (doh EE-tah-shee mah-shteh)"}],"say":"doh-ee-tah-shee-mah-shteh","kana":"どういたしまして","romaji":"dō itashimashite","score":98},{"id":"japan-vocab-01-22","deck":"fareast","topic":"Polite phrases","q":"How do you say 'I don't understand' in Japanese?","a":"wakarimasen","accept":[],"wrong":["sumimasen","hanasemasen","irimasen"],"explain":"Wakarimasen means 'I don't understand'.","hook":"'Wah-kah-ree-mah-sen' - lost at sea.","difficulty":3,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"I don't understand. 分かりません。 Wakarimasen. (wah-kah-ree-mah-sen)"}],"say":"wah-kah-ree-mah-sen","kana":"わかりません","romaji":"wakarimasen","kanji":"分かりません","score":98},{"id":"japan-vocab-01-23","deck":"fareast","topic":"Polite phrases","q":"What do you say when finishing a meal to thank the host or chef in Japanese?","a":"gochisōsama deshita","accept":["gochisosama deshita","gochisousama deshita","gochisōsama"],"wrong":["itadakimasu","dō itashimashite","otsukaresama deshita"],"explain":"Gochisōsama deshita ('it was delicious') is said when finishing a meal; itadakimasu is said before starting one.","hook":"Done eating = 'go-chee-soh-sah-mah'.","difficulty":3,"sources":[{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"It was delicious. (when finishing a meal) ご馳走さまでした。 ( Gochisōsama deshita. )"},{"url":"https://en.wikivoyage.org/wiki/Japanese_phrasebook","title":"Japanese phrasebook – Travel guide at Wikivoyage","quote":"If your meal was good, thank the chef or staff with Gochisōsama deshita when leaving, and you'll get an extra-hearty thank you in return!"}],"say":"goh-chee-soh-sah-mah deh-shee-tah","kana":"ごちそうさまでした","romaji":"gochisōsama deshita","kanji":"ご馳走さまでした","score":96},{"id":"vault-04-01","deck":"vault","topic":"EV bridge","q":"Going from equity value to enterprise value, which balance sheet item is subtracted?","a":"Cash and cash equivalents","accept":["cash","cash and equivalents","cash & cash equivalents","cash and cash equivalents"],"wrong":["Preferred stock","Total debt","Noncontrolling interest"],"explain":"EV = equity value + debt + preferred stock + noncontrolling interest - cash and equivalents. Cash is subtracted because, in theory, an acquirer can use the target's cash to pay down part of the assumed debt.","hook":"Add the claims, subtract the cash.","difficulty":1,"sources":[{"url":"https://corporatefinanceinstitute.com/resources/valuation/what-is-enterprise-value-ev","title":"Enterprise Value (EV) - Formula, Definition and Examples of EV","quote":"EV = Common Shares + Preferred Shares + Market Value of Debt + Noncontrolling Interest – Cash and Equivalents"},{"url":"https://www.wallstreetprep.com/knowledge/enterprise-value","title":"Enterprise Value (TEV) | Formula + Calculator","quote":"The rationale behind incorporating net debt rather than gross debt is that the cash sitting on a company’s balance sheet could hypothetically be used to pay down outstanding debt if deemed necessary."}],"score":93},{"id":"vault-04-02","deck":"vault","topic":"EV bridge","q":"Going from equity value to enterprise value, is preferred stock added or subtracted?","a":"Added","accept":["add","added to EV","plus"],"wrong":["Subtracted","Ignored","Netted against cash"],"explain":"Preferred stock is a non-common claim that is treated more like debt: it pays a fixed dividend, ranks ahead of common stock, and normally must be repaid in an acquisition.","hook":"Preferred behaves like debt, so it goes on the same side as debt.","difficulty":1,"sources":[{"url":"https://www.wallstreetprep.com/knowledge/equity-value-to-enterprise-value-bridge","title":"Equity Value to Enterprise Value Bridge | Formula + Calculator","quote":"From there, the company's net debt (i.e. total debt less cash ), preferred stock , and non-controlling interest (i.e. minority interest ) are added to the equity value."},{"url":"https://corporatefinanceinstitute.com/resources/valuation/what-is-enterprise-value-ev","title":"Enterprise Value (EV) - Formula, Definition and Examples of EV","quote":"They are treated more as debt, in this case, because they pay a fixed amount of dividends and have a higher priority in asset and earning claims than common stock. In an acquisition, they normally must be repaid just like debt."}],"score":97},{"id":"vault-04-03","deck":"vault","topic":"EV bridge","q":"Going from equity value to enterprise value, is noncontrolling (minority) interest added or subtracted?","a":"Added","accept":["add","added to EV","plus"],"wrong":["Subtracted","Ignored","Netted against cash"],"explain":"Noncontrolling interest is added because the parent consolidates all of the subsidiary's results, so EV must include the funding for the minority stake it does not own.","hook":"Consolidated in the numbers, so consolidated in the value.","difficulty":1,"sources":[{"url":"https://www.wallstreetprep.com/knowledge/enterprise-value","title":"Enterprise Value (TEV) | Formula + Calculator","quote":"Enterprise Value (TEV) = Equity Value + Net Debt + Preferred Stock + Minority Interest"},{"url":"https://trainingthestreet.com/resources/what-is-enterprise-value","title":"What is Enterprise Value? - Training The Street","quote":"However, when we calculate EV, we need to include 100% of all the operating assets that the company consolidates – we therefore need to include the funding for the minority stake in the consolidated, but non-wholly owned assets (i.e. the NCI)."}],"score":97},{"id":"vault-04-04","deck":"vault","topic":"Noncontrolling interest","q":"What percentage of a consolidated subsidiary's revenues, expenses and cash flow does the parent include in its own numbers, which is why NCI is added to EV?","a":"100%","accept":["100","100 percent","one hundred percent","all"],"wrong":["50%","Its ownership percentage","80%"],"explain":"Under consolidation the parent reports 100% of the subsidiary's results even though it owns less than 100%, so NCI is added to keep EV consistent with consolidated metrics like EBITDA.","hook":"Own 70%, report 100%: NCI fills the 30% gap.","difficulty":2,"sources":[{"url":"https://corporatefinanceinstitute.com/resources/valuation/what-is-enterprise-value-ev","title":"Enterprise Value (EV) - Formula, Definition and Examples of EV","quote":"We add this noncontrolling interest to the calculation of EV because the parent company has consolidated financial statements with that noncontrolling interest; meaning the parent includes 100% of the revenues, expenses, and cash flow in its numbers even though it doesn’t own 100% of the business."},{"url":"https://trainingthestreet.com/resources/what-is-enterprise-value","title":"What is Enterprise Value? - Training The Street","quote":"However, when we calculate EV, we need to include 100% of all the operating assets that the company consolidates – we therefore need to include the funding for the minority stake in the consolidated, but non-wholly owned assets (i.e. the NCI)."}],"score":96},{"id":"vault-04-05","deck":"vault","topic":"Noncontrolling interest","q":"A noncontrolling interest arises when a parent owns more than what percentage of a subsidiary, but less than 100%?","a":"50%","accept":["50","50 percent","fifty percent"],"wrong":["20%","33%","75%"],"explain":"Noncontrolling interest is the portion of a subsidiary not owned by a parent that holds a greater than 50% but less than 100% stake and consolidates the subsidiary.","hook":"Over half = control = consolidate.","difficulty":2,"sources":[{"url":"https://corporatefinanceinstitute.com/resources/valuation/what-is-enterprise-value-ev","title":"Enterprise Value (EV) - Formula, Definition and Examples of EV","quote":"Noncontrolling interest is the portion of a subsidiary not owned by the parent company (who owns a greater than 50% but less than 100% position in the subsidiary)."},{"url":"https://trainingthestreet.com/resources/what-is-enterprise-value","title":"What is Enterprise Value? - Training The Street","quote":"If a parent company owns between 50+% to 80% of a subsidiary, it will likely use the consolidation method to report the results of that entity"}],"score":91},{"id":"vault-04-06","deck":"vault","topic":"EV bridge","q":"If a company raises new debt and keeps the proceeds as cash, what happens to its enterprise value?","a":"No change","accept":["unchanged","stays the same","nothing","no effect","no impact"],"wrong":["Increases","Decreases","Doubles"],"explain":"The new debt raises total debt, but the proceeds raise cash by the same amount, so net debt and therefore EV are unchanged.","hook":"Debt up, cash up: net debt flat.","difficulty":3,"sources":[{"url":"https://www.wallstreetprep.com/knowledge/equity-value-to-enterprise-value-bridge","title":"Equity Value to Enterprise Value Bridge | Formula + Calculator","quote":"However, a critical concept to understand is that the addition of new debt does NOT increase a company's enterprise value. The reason is newly raised capital via debt financing flows directly into the cash balance of the company, so the two offset each other, since net debt is the difference between total debt and cash."}],"score":96},{"id":"vault-04-07","deck":"vault","topic":"Equity value","q":"Diluted equity value equals the share price multiplied by what?","a":"Diluted shares outstanding","accept":["diluted shares","fully diluted shares","fully diluted shares outstanding","total diluted shares outstanding"],"wrong":["Basic shares outstanding","Authorized shares","Treasury shares"],"explain":"Equity value is calculated on a fully diluted basis, so potentially dilutive securities such as in-the-money options, warrants and convertibles are counted.","hook":"Price x diluted count.","difficulty":1,"sources":[{"url":"https://www.wallstreetprep.com/knowledge/equity-value-to-enterprise-value-bridge","title":"Equity Value to Enterprise Value Bridge | Formula + Calculator","quote":"Equity Value = Latest Closing Share Price × Total Diluted Shares Outstanding"},{"url":"https://corporatefinanceinstitute.com/resources/valuation/what-is-enterprise-value-ev","title":"Enterprise Value (EV) - Formula, Definition and Examples of EV","quote":"Equity value is found by taking the company’s fully-diluted shares outstanding and multiplying them by the stock’s current market price. Fully diluted means that it includes in-the-money options , warrants, and convertible securities, aside from just the basic shares outstanding."}],"score":97},{"id":"vault-04-08","deck":"vault","topic":"EV vs equity value","q":"Enterprise value is described as neutral to what, which makes it well suited to comparing companies with different financing?","a":"Capital structure","accept":["the capital structure","financing","leverage","capital structure neutral"],"wrong":["Share price","Company size","Industry"],"explain":"Because EV covers all capital providers, it is indifferent to how the business is financed, so EV multiples are independent of capital structure while equity multiples are affected by leverage.","hook":"EV doesn't care how you pay for the business.","difficulty":2,"sources":[{"url":"https://www.wallstreetprep.com/knowledge/equity-value-to-enterprise-value-bridge","title":"Equity Value to Enterprise Value Bridge | Formula + Calculator","quote":"The enterprise value metric is capital structure neutral and indifferent to discretionary financing decisions, making it well-suited for purposes of relative valuation and comparisons among different companies."},{"url":"https://www.fe.training/free-resources/valuation/valuation-multiples/","title":"Valuation Multiples - Financial Edge Training","quote":"This means that equity multiples are impacted by differing capital structures, whereas enterprise value multiples are independent of capital structure."}],"score":94},{"id":"vault-04-09","deck":"vault","topic":"EV bridge","q":"Going from equity value to enterprise value, are equity method investments added or subtracted?","a":"Subtracted","accept":["subtract","subtracted","deducted","deduct","minus","removed"],"wrong":["Added","Ignored","Added at book value"],"explain":"Equity method investees are not consolidated, so they generate no EBITDA for the parent; removing their value from EV keeps the same assets in the numerator and denominator of EV/EBITDA.","hook":"No EBITDA from it, so no EV for it.","difficulty":3,"sources":[{"url":"https://trainingthestreet.com/resources/what-is-enterprise-value","title":"What is Enterprise Value? - Training The Street","quote":"Depending on the ownership level, the parent may use the Equity Method of accounting or it may simply account for the stake as an investment on the balance sheet. In either case, the stake would be categorized as a long-term investment (LTI). When calculating the EV of the parent, LTI is subtracted from the total. ... Because the LTIs are not consolidated, they are not part of the parent's “operating” assets and do not generate EBITDA."},{"url":"https://premieur.co/institute/valuation/enterprise-value-and-equity-value","title":"Enterprise value vs equity value · Premieur Institute","quote":"When a company owns a stake of roughly 20 to 50 percent in another business, it accounts for it under the equity method: one line on the balance sheet and a share of the investee's profit below operating income. That profit is not in EBITDA, so the investment's value must be taken out of EV, otherwise the numerator includes value the denominator does not."}],"score":93},{"id":"vault-04-10","deck":"vault","topic":"Treasury stock method","q":"Under ASC 260's treasury stock method, exercise proceeds are assumed to repurchase common stock at what price?","a":"Average market price","accept":["average market price during the period","average price","average share price","average stock price"],"wrong":["Exercise price","Period-end closing price","Book value per share"],"explain":"The treasury stock method assumes the proceeds from exercising options and warrants are used to buy back common stock at the average market price during the period.","difficulty":2,"sources":[{"url":"https://dart.deloitte.com/USDART/home/codification/presentation/asc260-10/roadmap-earnings-per-share/chapter-4-diluted-eps/4-2-treasury-stock-method","title":"4.2 Treasury Stock Method | DART – Deloitte Accounting Research Tool","quote":"The proceeds from exercise shall be assumed to be used to purchase common stock at the average market price during the period."},{"url":"https://viewpoint.pwc.com/dt/us/en/pwc/accounting_guides/financial_statement_/financial_statement___18_US/chapter_7_earnings_p_US/75_diluted_eps_US.html","title":"7.5 Diluted EPS (PwC Viewpoint)","quote":"Treasury stock method: A method of recognizing the use of proceeds that could be obtained upon exercise of options and warrants in computing diluted EPS. It assumes that any proceeds would be used to purchase common stock at the average market price during the period."}],"score":99},{"id":"vault-04-11","deck":"vault","topic":"Treasury stock method","q":"The treasury stock method is applied only to options and warrants that are what?","a":"In-the-money","accept":["in the money","ITM"],"wrong":["Out-of-the-money","At-the-money","Expired"],"explain":"Out-of-the-money options are excluded because a holder would not exercise them and including them would generally be antidilutive.","hook":"No money, no dilution.","difficulty":1,"sources":[{"url":"https://dart.deloitte.com/USDART/home/codification/presentation/asc260-10/roadmap-earnings-per-share/chapter-4-diluted-eps/4-2-treasury-stock-method","title":"4.2 Treasury Stock Method | DART – Deloitte Accounting Research Tool","quote":"The treasury stock method is only applied to options and warrants that are in-the-money from the perspective of the counterparty."},{"url":"https://corporatefinanceinstitute.com/resources/accounting/treasury-stock-method","title":"Treasury Stock Method - Definition, Formula, and Example","quote":"The treasury stock method is a way for companies to calculate how many additional shares may be generated from outstanding in-the-money warrants and options."}],"score":98},{"id":"vault-04-12","deck":"vault","topic":"Diluted shares","q":"Which method is used to calculate the dilutive effect of stock options and warrants?","a":"Treasury stock method","accept":["TSM","treasury stock","the treasury stock method"],"wrong":["If-converted method","Two-class method","Equity method"],"explain":"Options and warrants use the treasury stock method, while convertible debt and convertible preferred stock use the if-converted method.","difficulty":1,"sources":[{"url":"https://rsmus.com/content/dam/rsm/insights/financial-reporting/1pdf/financial-reporting-insights-earnings-per-share-202410.pdf","title":"Financial reporting insights: earnings per share (RSM, October 2024)","quote":"Warrants Treasury stock method"},{"url":"https://asc.understandingaccounting.org/asc/260/10","title":"ASC 260-10 Overall — ASC Reader","quote":"Diluted EPS uses the treasury stock method for options, warrants, and share-based awards"}],"score":96},{"id":"vault-04-13","deck":"vault","topic":"Convertibles","q":"Which method is used to reflect convertible debt in diluted EPS?","a":"If-converted method","accept":["if-converted","if converted method","if converted","the if-converted method"],"wrong":["Treasury stock method","Two-class method","Reverse treasury stock method"],"explain":"Convertible debt and convertible preferred stock use the if-converted method, which assumes conversion into common shares.","difficulty":1,"sources":[{"url":"https://rsmus.com/content/dam/rsm/insights/financial-reporting/1pdf/financial-reporting-insights-earnings-per-share-202410.pdf","title":"Financial reporting insights: earnings per share (RSM, October 2024)","quote":"Convertible debt If-converted method"},{"url":"https://farhatlectures.com/if-converted-method/","title":"If-Converted Method for Diluted EPS | Farhat Lectures","quote":"Convertible bonds and convertible preferred stock. Stock options and warrants use the treasury stock method instead."}],"score":97},{"id":"vault-04-14","deck":"vault","topic":"Convertibles","q":"Under the if-converted method, on what tax basis is a convertible bond's interest expense added back to the EPS numerator?","a":"Net of tax","accept":["after-tax","after tax","after-tax basis","net of taxes","post-tax"],"wrong":["Pre-tax","Gross of tax","At face value"],"explain":"If the bonds had converted, the company would save the interest but pay more income tax, so net income rises only by the after-tax interest.","hook":"Interest is tax-deductible, so the add-back is after tax.","difficulty":2,"sources":[{"url":"https://www.lw.com/en/offices/admin/upload/SiteAttachments/Demystifying-Convertible-Bonds-April-2024.pdf","title":"Demystifying Convertible Bonds - April 2024 - Latham & Watkins","quote":"the after-tax effect of the interest expense for the notes during the reporting period is added back to the numerator of EPS"},{"url":"https://farhatlectures.com/if-converted-method/","title":"If-Converted Method for Diluted EPS | Farhat Lectures","quote":"Interest expense reduces taxable income. If the bonds had been converted, the company would save the interest but pay more income tax, so net income rises only by the after-tax amount."}],"score":96},{"id":"vault-04-15","deck":"vault","topic":"Convertibles","q":"Under the if-converted method for convertible preferred stock, what is added back to the EPS numerator?","a":"Preferred dividends","accept":["the preferred dividends","convertible preferred dividends","preferred dividend"],"wrong":["After-tax interest","Common dividends","Depreciation"],"explain":"The preferred dividends subtracted in basic EPS are added back in full, with no tax effect, and the shares issuable on conversion are added to the denominator.","difficulty":2,"sources":[{"url":"https://farhatlectures.com/if-converted-method/","title":"If-Converted Method for Diluted EPS | Farhat Lectures","quote":"Convertible preferred stock | Add back the preferred dividends subtracted in basic EPS (no tax effect) | Add the common shares issuable on conversion"},{"url":"https://asc.understandingaccounting.org/asc/260/10","title":"ASC 260-10 Overall — ASC Reader","quote":"the if-converted method for convertible securities (add back preferred dividends or after-tax interest and assume conversion at the beginning of the period)"}],"score":98},{"id":"vault-04-16","deck":"vault","topic":"Convertibles","q":"A convertible bond's conversion price equals its principal amount divided by what?","a":"Conversion ratio","accept":["the conversion ratio","conversion rate","the conversion rate"],"wrong":["Share price","Coupon rate","Conversion premium"],"explain":"The conversion ratio is the number of shares received per bond (usually per $1,000 of principal); principal divided by that ratio gives the effective price paid per share.","hook":"Price per share = dollars / shares.","difficulty":2,"sources":[{"url":"https://www.ey.com/content/dam/ey-unified-site/ey-com/en-us/technical/accountinglink/documents/ey-frdbb1971-07-08-2026.pdf","title":"Financial Reporting Developments - Earnings per share (EY)","quote":"Conversion price = (Convertible bond’s principal amount) ÷ (Conversion ratio) = $1,000 ÷ 20 = $50."},{"url":"https://www.footnotesanalyst.com/convertible-bonds-us-gaap-and-hidden-financing-costs","title":"Convertible bonds: US GAAP and hidden financing costs","quote":"The conversion price is the principal divided by the conversion ratio, and is the effective price per share the holder pays by giving up the bond."}],"score":98},{"id":"vault-04-17","deck":"vault","topic":"Convertibles","q":"How many shares does $1,000 of convertible bond principal convert into at a $25 conversion price?","a":"40","accept":["40 shares","forty"],"wrong":["25","400","4"],"explain":"Shares per bond equal principal divided by conversion price: $1,000 / $25 = 40 shares per $1,000 principal.","difficulty":2,"sources":[{"url":"https://www.mayerbrown.com/-/media/files/perspectives-events/publications/brochures/2025/mb-convertible-bonds-2025.pdf?rev=503a9984bccc4908bff62793c9370594","title":"Convertible Bonds - Mayer Brown (2025)","quote":"Initial Conversion Rate = $1,000 principal amount of notes divided by conversion price – = $1,000 divided by $25 per share = 40 shares per $1,000 principal amount of bonds"},{"url":"https://www.footnotesanalyst.com/convertible-bonds-us-gaap-and-hidden-financing-costs","title":"Convertible bonds: US GAAP and hidden financing costs","quote":"The conversion ratio is the number of shares received on converting a bond, usually stated per $1,000 of principal. The conversion price is the principal divided by the conversion ratio"}],"score":98},{"id":"vault-04-18","deck":"vault","topic":"Convertibles in EV","q":"In the enterprise value bridge, how is an out-of-the-money convertible bond counted?","a":"As debt","accept":["debt","face value as debt","straight debt","as straight debt"],"wrong":["As diluted shares","As cash","As noncontrolling interest"],"explain":"When the share price is below the conversion price, the holder is unlikely to convert, so the face value is counted as debt and no shares are added.","hook":"Out of the money: stays a bond.","difficulty":2,"sources":[{"url":"https://bpb-us-w2.wpmucdn.com/voices.uchicago.edu/dist/8/3622/files/2025/09/Equity-Value-and-Enterprise-Value-Guide-_-Questions-and-Answers.pdf","title":"Equity Value and Enterprise Value Questions & Answers","quote":"If the Convertible Bonds are out-of-the-money, then you count the face value of the convertibles as part of the company’s Debt."},{"url":"https://ibinterviewquestions.com/blog/convertible-bonds-notes-explained","title":"Convertible Bonds Explained for IB Interviews","quote":"If the stock price is below the conversion price (out of the money), the convertible is treated as debt and added to enterprise value."}],"score":93},{"id":"vault-04-19","deck":"vault","topic":"Convertibles in EV","q":"What error occurs if an in-the-money convertible is counted both as debt in the EV bridge and as diluted shares?","a":"Double counting","accept":["double-counting","double count","double-count","double counted"],"wrong":["Antidilution","Negative net debt","Circular reference"],"explain":"An in-the-money convertible should be added as diluted shares and removed from debt; leaving it in both places counts the same claim twice and overstates EV.","hook":"One claim, one place.","difficulty":3,"sources":[{"url":"https://ibinterviewquestions.com/guides/valuation-investment-banking/convertible-securities-warrants-valuation-dilution","title":"Convertible Securities and Warrants: Valuation and Dilution","quote":"The critical rule: never include a convertible in both the debt component of EV and the diluted share count simultaneously."},{"url":"https://premieur.co/institute/valuation/enterprise-value-and-equity-value","title":"Enterprise value vs equity value · Premieur Institute","quote":"If the shares are counted and the bond is also left in net debt, the same claim appears twice and EV is overstated by the face value of the bond."}],"score":93},{"id":"vault-04-20","deck":"vault","topic":"Diluted shares","q":"Potential common shares whose inclusion would increase EPS are described as what, and are excluded from diluted EPS?","a":"Antidilutive","accept":["anti-dilutive","antidilutive securities"],"wrong":["Participating","Contingently issuable","Nonvested"],"explain":"ASC 260 does not assume conversion, exercise or contingent issuance of securities that would have an antidilutive effect on EPS.","difficulty":2,"sources":[{"url":"https://kpmg.com/kpmg-us/content/dam/kpmg/frv/pdf/2025/handbook-earnings-per-share-2025.pdf","title":"Handbook: Earnings per share - KPMG","quote":"Potential common shares are not included in diluted EPS if they are antidilutive – i.e. the exercise or conversion would increase EPS."},{"url":"https://dart.deloitte.com/USDART/home/codification/presentation/asc260-10/roadmap-earnings-per-share/chapter-4-diluted-eps/4-1-background","title":"4.1 Background | DART – Deloitte Accounting Research Tool","quote":"45-17 The computation of diluted EPS shall not assume conversion, exercise, or contingent issuance of securities that would have an antidilutive effect on EPS."}],"score":97},{"id":"vault-04-21","deck":"vault","topic":"Treasury stock method","q":"Under ASC 260's treasury stock method, options are assumed exercised at what point (unless issued later)?","a":"Beginning of the period","accept":["beginning of period","start of the period","start of period","the beginning of the period","beginning of the reporting period"],"wrong":["End of the period","Grant date","Vesting date"],"explain":"Exercise is assumed at the beginning of the period, or at the time of issuance if later, and the resulting incremental shares go into the diluted EPS denominator.","difficulty":3,"sources":[{"url":"https://dart.deloitte.com/USDART/home/codification/presentation/asc260-10/roadmap-earnings-per-share/chapter-4-diluted-eps/4-2-treasury-stock-method","title":"4.2 Treasury Stock Method | DART – Deloitte Accounting Research Tool","quote":"Exercise of options and warrants shall be assumed at the beginning of the period (or at time of issuance, if later) and common shares shall be assumed to be issued."},{"url":"https://rsmus.com/content/dam/rsm/insights/financial-reporting/1pdf/financial-reporting-insights-earnings-per-share-202410.pdf","title":"Financial reporting insights: earnings per share (RSM, October 2024)","quote":"Assume the outstanding options and warrants are exercised at the beginning of the reporting period (or at time of issuance, if later) and common shares are issued at that time."}],"score":99},{"id":"vault-04-22","deck":"vault","topic":"Treasury stock method","q":"Under the treasury stock method, how many net new shares come from 15,000 in-the-money options with a $7 exercise price and a $10 average share price?","a":"4,500","accept":["4500","4,500 shares","4500 shares"],"wrong":["15,000","10,500","5,000"],"explain":"Proceeds of 15,000 x $7 = $105,000 buy back $105,000 / $10 = 10,500 shares, so net new shares are 15,000 - 10,500 = 4,500.","hook":"Shortcut: options x (price - strike) / price.","difficulty":2,"sources":[{"url":"https://corporatefinanceinstitute.com/resources/accounting/treasury-stock-method","title":"Treasury Stock Method - Definition, Formula, and Example","quote":"Using these proceeds, the company can buy $105,000 / $10 = 10,500 shares at the average market price. Thus, the net increase in shares outstanding is 15,000 – 10,500 = 4,500."},{"url":"https://farhatlectures.com/treasury-stock-method","title":"Treasury Stock Method: Diluted EPS for Options and Warrants","quote":"When exercise cash is the only assumed proceeds, use this shortcut for dilutive options: incremental shares = number of options × (average market price − exercise price) ÷ average market price ."}],"score":98},{"id":"vault-04-23","deck":"vault","topic":"Multiples pairing","q":"Because EBITDA is calculated before interest expense, it pairs with which value measure in a multiple?","a":"Enterprise value","accept":["EV","TEV","total enterprise value"],"wrong":["Equity value","Market capitalization","Book value of equity"],"explain":"EBITDA does not deduct net interest expense and represents all investors, so it pairs with enterprise value; an Equity Value/EBITDA multiple is considered meaningless.","difficulty":1,"sources":[{"url":"https://breakingintowallstreet.com/kb/valuation/valuation-multiples","title":"Valuation Multiples: Full Tutorial, Excel, and Video","quote":"For example, EBITDA does not deduct a company’s Net Interest Expense, and it represents all the investors in the company. Therefore, it always pairs with Enterprise Value."},{"url":"https://macabacus.com/valuation/multiples","title":"Valuation Multiples: Enterprise vs Equity, P/E, EBITDA, EBIT, Sales | Macabacus","quote":"For example, when talking about the EV/EBITDA multiple, we would simply say “EBITDA multiple”, because the only sensible numerator is EV."}],"score":95},{"id":"vault-04-24","deck":"vault","topic":"Multiples pairing","q":"The P/E multiple is equivalent to equity value divided by what?","a":"Net income","accept":["earnings","net earnings"],"wrong":["EBITDA","Revenue","EBIT"],"explain":"P/E is share price over EPS; dividing both equity value and net income by fully diluted shares gives the same ratio.","difficulty":1,"sources":[{"url":"https://macabacus.com/valuation/multiples","title":"Valuation Multiples: Enterprise vs Equity, P/E, EBITDA, EBIT, Sales | Macabacus","quote":"Note that the P/E multiple equals the ratio of equity value to net Income, in which the numerator and denominator are both are divided by the number of fully diluted shares."},{"url":"https://breakingintowallstreet.com/kb/valuation/valuation-multiples","title":"Valuation Multiples: Full Tutorial, Excel, and Video","quote":"Equity Value / Net Income (P / E): Tells you how valuable a company is in relation to its after-tax profits"}],"score":98},{"id":"vault-04-25","deck":"vault","topic":"Multiples pairing","q":"Is price-to-book (P/B) an enterprise value multiple or an equity value multiple?","a":"Equity value multiple","accept":["equity value","equity","equity multiple","equity value-based"],"wrong":["Enterprise value multiple","Both equally","Neither"],"explain":"Book value represents only the common shareholders, so P/B is an equity value multiple, alongside P/E and the PEG ratio.","difficulty":1,"sources":[{"url":"http://wallstreetprep.com/knowledge/valuation-multiples","title":"Valuation Multiples Primer | Formula + Calculator","quote":"Enterprise Value Multiples | Equity Value Multiples * * EV/EBITDA | * P/E Ratio * * EV/EBIT | * PEG Ratio * * EV/Revenue | * Price/Book Ratio (P/B)"},{"url":"https://breakingintowallstreet.com/kb/valuation/valuation-multiples","title":"Valuation Multiples: Full Tutorial, Excel, and Video","quote":"OR does the metric represent just the common shareholders? If so, it pairs with Equity Value (e.g., Book Value )."}],"score":97},{"id":"vault-04-26","deck":"vault","topic":"Multiples pairing","q":"Denominators of enterprise value multiples must be computed before which expense that goes to lenders?","a":"Interest expense","accept":["interest","net interest expense"],"wrong":["Cost of goods sold","Operating expenses","Depreciation"],"explain":"EV multiples use metrics relevant to all stakeholders, so the denominator is before interest, preferred dividends and minority interest expense; a metric that deducts net interest pairs with equity value.","hook":"Above the interest line = EV; below it = equity.","difficulty":2,"sources":[{"url":"https://macabacus.com/valuation/multiples","title":"Valuation Multiples: Enterprise vs Equity, P/E, EBITDA, EBIT, Sales | Macabacus","quote":"Therefore, the relevant denominator must be computed before interest expense, preferred dividends, and minority interest expense."},{"url":"https://breakingintowallstreet.com/kb/valuation/valuation-multiples","title":"Valuation Multiples: Full Tutorial, Excel, and Video","quote":"Does the metric deduct the company’s Net Interest Expense? If so, it pairs with Equity Value (e.g., Net Income )."}],"score":96},{"id":"vault-04-27","deck":"vault","topic":"Multiples pairing","q":"According to CFA Institute, EV/EBITDA is preferred to P/EBITDA because EBITDA is a flow to whom?","a":"All providers of capital","accept":["all capital providers","all investors","all holders of capital","debt and equity holders"],"wrong":["Common shareholders only","Preferred shareholders only","Lenders only"],"explain":"EBITDA is a pre-interest number, so it belongs to all capital providers and matches EV; equity value only covers shareholders.","difficulty":3,"sources":[{"url":"https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/market-based-valuation-price-enterprise-value-multiples","title":"Market-Based Valuation: Price and Enterprise Value Multiples | CFA Institute","quote":"EV/EBITDA is preferred to P/EBITDA because EBITDA, as a pre-interest number, is a flow to all providers of capital."},{"url":"https://macabacus.com/valuation/multiples","title":"Valuation Multiples: Enterprise vs Equity, P/E, EBITDA, EBIT, Sales | Macabacus","quote":"Similarly, an Equity Value/EBITDA multiple is meaningless because the numerator applies only to shareholders, while the denominator accrues to all holders of capital."}],"score":99},{"id":"vault-04-28","deck":"vault","topic":"Multiples pairing","q":"For comparing companies with different capital structures, which is conceptually preferable: P/S or EV/Sales?","a":"EV/Sales","accept":["EV/S","EV/Revenue","EV to sales","enterprise value to sales","EV/sales"],"wrong":["P/S","P/E","P/B"],"explain":"Sales is a pre-financing metric that belongs to all capital providers, so pairing it with EV makes companies with different leverage comparable.","difficulty":2,"sources":[{"url":"https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/market-based-valuation-price-enterprise-value-multiples","title":"Market-Based Valuation: Price and Enterprise Value Multiples | CFA Institute","quote":"The ratio of EV to total sales is conceptually preferable to P/S because EV/S facilitates comparisons among companies with varying capital structures."},{"url":"https://www.fe.training/free-resources/valuation/valuation-multiples/","title":"Valuation Multiples - Financial Edge Training","quote":"This means that enterprise value and enterprise value multiples are independent of capital structure."}],"score":99},{"id":"vault-04-29","deck":"vault","topic":"Convertibles","q":"Why does the if-converted method have no share buyback offset, unlike the treasury stock method?","a":"No cash is received","accept":["no cash received","no cash","company receives no cash","no proceeds","no exercise proceeds"],"wrong":["Shares are antidilutive","Interest is tax-deductible","Bonds are out-of-the-money"],"explain":"Option exercise brings in cash that the treasury stock method assumes is used to repurchase shares; converting a bond brings in no cash, so all conversion shares are added.","hook":"No cash in, nothing to buy back with.","difficulty":3,"sources":[{"url":"https://ibinterviewquestions.com/guides/valuation-investment-banking/convertible-securities-warrants-valuation-dilution","title":"Convertible Securities and Warrants: Valuation and Dilution","quote":"If-converted method: Used for convertible bonds and convertible preferred stock. Assumes the convertible is converted into common shares. Since the company receives no cash upon conversion (unlike option exercise), there is no buyback offset."},{"url":"https://bpb-us-w2.wpmucdn.com/voices.uchicago.edu/dist/8/3622/files/2025/09/Equity-Value-and-Enterprise-Value-Guide-_-Questions-and-Answers.pdf","title":"Equity Value and Enterprise Value Questions & Answers","quote":"Treatment is “either or” – they count as debt, or count 100% as additional shares, with no Treasury Stock Method involved"}],"score":95}];
